#!/bin/sh
# Stages what the Flutter editor reads from the rest of the repository into assets/generated:
# the editor's control catalogue and glyphs (generated by fotufilm-controls and shared/Glyphs),
# the Material Symbols the web editor bundles, and the Satoshi typeface the web editor loads from
# Fontshare. Nothing staged is committed; run this before `flutter build` or `flutter run`.
set -eu
here=$(cd "$(dirname "$0")/.." && pwd)
repo=$(cd "$here/.." && pwd)
out="$here/assets/generated"
mkdir -p "$out/glyphs" "$out/fonts"

node --input-type=module -e "
import * as catalogue from '$repo/web/src/generated/controls.js';
process.stdout.write(JSON.stringify(catalogue));
" > "$out/controls.json"
cp "$repo/web/src/material-symbols.json" "$out/material-symbols.json"
cp "$repo/web/src/assets/fotufilm-wordmark.svg" "$repo/web/public/app-icon.png" "$out/"
find "$repo/web/public/glyphs" -name 'fotu.*.svg' -exec cp {} "$out/glyphs/" \;

if [ ! -f "$out/fonts/Satoshi-Regular.otf" ]; then
  tmp=$(mktemp -d)
  curl -fsSL -o "$tmp/satoshi.zip" "https://api.fontshare.com/v2/fonts/download/satoshi"
  unzip -q -j "$tmp/satoshi.zip" 'Satoshi_Complete/Fonts/OTF/Satoshi-Regular.otf' \
    'Satoshi_Complete/Fonts/OTF/Satoshi-Medium.otf' 'Satoshi_Complete/Fonts/OTF/Satoshi-Bold.otf' \
    -d "$out/fonts"
  rm -rf "$tmp"
fi
echo "Staged $(ls "$out/glyphs" | wc -l | tr -d ' ') glyphs, the control catalogue and Satoshi in $out"
